-- Patch for already-seeded environments only.
--
-- Syncs the Health Event Details section's section_ui_schema to the canonical
-- definition in g2p_register_sections.sql (line
-- 'livestock_health_event_details_section_01'). The seed only INSERTs and never
-- touches an existing row, so environments seeded before that line changed
-- keep the old dialog forever; this re-applies the whole schema by section_id.
--
-- Why: the official staff-ui cannot fill a dialog column from another
-- section's rows ("sibling-table" source) nor cascade one dialog column from
-- another, so the Ear Tag picker rendered EMPTY (and, on Vaccination, the
-- Vaccine list too). Ear Tag is now a text input (server-checked against this
-- submission's animals), Vaccine the plain VACCINE_TYPE list (server-checked
-- against the animal's species), Species is filled by the server from the
-- animal, and dialog conditions use operators the official UI supports.
-- Generated from the seed line; keep the two in sync.
UPDATE "public"."g2p_register_sections"
SET section_ui_schema = '{"panels": [{"panels": [{"widgets": [{"widget": "dialog-table", "widget-id": "ls_health_event_details_table", "widget-type": "dialog-table", "widget-label": "ls_health_event_details", "widget-readonly": false, "widget-data-path": "a40e4a02-1b82-5b31-89df-71624bd96545.records", "widget-data-columns": [{"widget": "text", "column-key": "ear_tag_id", "widget-type": "input", "widget-label": "Livestock Ear Tag", "widget-autofill": {"fields": {"age": "age", "species": "species"}, "matchField": "ear_tag_id", "sourceWidgetId": "ls_animal_details_table"}, "widget-readonly": false, "widget-required": true, "widget-data-path": "ear_tag_id", "widget-placeholder": "ET + 10 digits, e.g. ET0000000123"}, {"widget": "select", "column-key": "species", "widget-type": "input", "widget-label": "Species", "widget-readonly": true, "widget-data-path": "species", "widget-data-source": {"type": "api", "method": "POST", "params": {"page_size": 500, "attribute_id": "LIVESTOCK_SPECIES"}, "service": "attributes", "endpoint": "values", "labelKey": "value_display", "valueKey": "value_id"}}, {"widget": "text", "column-key": "age", "widget-type": "input", "widget-label": "Age", "widget-readonly": true, "widget-data-path": "age"}, {"widget": "select", "column-key": "event_type", "widget-type": "input", "widget-label": "Event Type", "widget-readonly": false, "widget-required": true, "widget-data-path": "event_type", "widget-data-source": {"type": "static", "options": [{"label": "DISEASE", "value": "DISEASE"}, {"label": "INJURY", "value": "INJURY"}, {"label": "TREATMENT", "value": "TREATMENT"}, {"label": "RECOVERY", "value": "RECOVERY"}]}}, {"widget": "select", "column-key": "disease_type", "widget-type": "input", "widget-label": "Disease", "widget-readonly": false, "widget-data-path": "disease_type", "widget-data-source": {"type": "api", "method": "POST", "params": {"page_size": 500, "attribute_id": "LIVESTOCK_DISEASE"}, "service": "attributes", "endpoint": "values", "labelKey"