pe": "input", "widget-label": "Location", "widget-readonly": false, "widget-data-path": "location", "widget-data-source": {"type": "static", "options": [{"label": "HOME", "value": "HOME"}, {"label": "VETERINARY", "value": "VETERINARY"}, {"label": "MARKET", "value": "MARKET"}, {"label": "FIELD", "value": "FIELD"}, {"label": "QUARANTINE_CENTER", "value": "QUARANTINE_CENTER"}, {"label": "OTHER", "value": "OTHER"}]}, "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}, {"widget": "text", "column-key": "location_details", "widget-type": "input", "widget-label": "Location Details", "widget-readonly": false, "widget-data-path": "location_details", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}, {"widget": "radio", "column-key": "is_notifiable", "widget-type": "input", "widget-label": "Notifiable Disease", "widget-readonly": false, "widget-required": true, "widget-data-path": "is_notifiable", "widget-data-source": {"type": "static", "options": [{"label": "YES", "value": true}, {"label": "NO", "value": false}]}, "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "value": "DISEASE", "operator": "equals"}}]}}, {"widget": "text", "column-key": "notes", "widget-type": "input", "widget-label": "Notes", "widget-readonly": false, "widget-data-path": "notes", "widget-data-options": {"actions": [{"action": "show", "condition": {"field": "event_type", "operator": "notEmpty"}}]}}], "widget-data-operations": {"add": true, "edit": true, "remove": true}, "widget-data-dialog-title-add": "Add ls_health_event_details", "widget-data-dialog-title-edit": "Edit ls_health_event_details"}], "panel-id": "vertical_panel_ls_health_event_details_1", "panel-orientation": "vertical"}], "panel-id": "horizontal_panel_ls_health_event_details", "panel-orientation": "horizontal"}], "section-id": "livestock_health_event_details_section_01", "section-title": "Health Event Details", "section-editable": true, "section-required-for-submit": false}'::jsonb
WHERE section_id = 'livestock_health_event_details_section_01';
